  return np.sum(np.cos(3*x)) + 0.1*np.sqrt(np.sum(x**2)) + 0.05*(x[0]*x[1])

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A 2-dimensional synthetic benchmark function combining periodic, polynomial, and interaction terms,
    modulated by a Gaussian envelope.

    Formula:
    f(x) = exp(-(x[0]**2 + x[1]**2)/20) * (
           2*np.cos(4*x[0]) + x[0]**3*0.01 + 0.5*x[1]**2 + 0.1*(x[0]*x[1]**2)
           )
    """
    return np.exp(-(x[0]**2 + x[1]**2)/20) * (
           2*np.cos(4*x[0]) + x[0]**3*0.01 + 0.5*x[1]**2 + 0.1*(x[0]*x[1]**2)
           )

